// 12.取消订阅，释放订阅相关资源
aclprofModelUnSubscribe (modelId);
pthread_join(subTid, NULL);
// 关闭读管道指针
close(subFd[0]);
// 释放config指针
aclprofDestroySubscribeConfig (config);
